import java.util.*;
import java.io.*;

public class Main {
    static int[] commonManager(int n, int[] manager, int[][] queries) {
        // manager[e] is the direct manager of employee e (manager[0] = -1 for the CEO)
        // Write your solution here
        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        int[] manager = new int[n];
        Arrays.fill(manager, -1);
        for (int i = 0; i < n - 1; i++) {
            in.nextToken();
            int m = (int) in.nval;
            in.nextToken();
            int e = (int) in.nval;
            manager[e] = m;
        }
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) {
            in.nextToken();
            queries[i][0] = (int) in.nval;
            in.nextToken();
            queries[i][1] = (int) in.nval;
        }
        int[] res = commonManager(n, manager, queries);
        StringBuilder sb = new StringBuilder();
        for (int x : res) sb.append(x).append('\n');
        System.out.print(sb);
    }
}
